54	fn parse_skill(path: &Path) -> Result<Skill> {
55	    let raw = fs::read_to_string(path)
56	        .with_context(|| format!("Failed to read skill definition: {:?}", path))?;
57	    let content = raw.trim_start();
58	    if !content.starts_with("---") {
59	        anyhow::bail!("Skill definition must start with `---`: {:?}", path);
60	    }
61	
62	    let rest = &content[3..];
63	    let (end, delimiter_len) = if let Some(pos) = rest.find("\r\n---") {
64	        (pos, 5)
65	    } else if let Some(pos) = rest.find("\n---") {
66	        (pos, 4)
67	    } else {
68	        anyhow::bail!("Could not find closing `---` in skill: {:?}", path);
69	    };
70	
71	    let metadata: SkillMetadata = serde_yaml::from_str(&rest[..end])
72	        .with_context(|| format!("Failed to parse skill frontmatter: {:?}", path))?;
73	    if metadata.name.trim().is_empty() || metadata.description.trim().is_empty() {
74	        anyhow::bail!("Skill name and description must not be empty: {:?}", path);
75	    }
76	
77	    let instructions = content[3 + end + delimiter_len..].trim().to_string();
78	    if instructions.is_empty() {
79	        anyhow::bail!("Skill instructions must not be empty: {:?}", path);
80	    }
81	
82	    Ok(Skill {
83	        metadata,
84	        instructions,
85	    })
86	}
