34	/// What to say when a tool call names a skill instead of a tool.
35	///
36	/// A reviewer called `engineering/environment` as a tool and was told only "Invalid tool
37	/// name format (expected server__tool)". It did not call the loader afterwards -- it
38	/// reported to the pull request that it HAD run the skill, which was read by a person.
39	///
40	/// It reached for that name because the prompt hands it one: skills are listed as
41	/// ``- `engineering/environment`: ...`` and the prose says "Load `engineering/environment`",
42	/// in the same backticked shape a tool name takes. Presenting them so they cannot be
43	/// confused is the better fix and belongs in the prompt; this is the message for when
44	/// the confusion happens anyway, and it names the call that works rather than the rule
45	/// that was broken -- measured three times in this project as the difference between a
46	/// refusal that is followed and one that is not.
47	///
48	/// Only for a name shaped like a skill path. Anything else keeps the format error,
49	/// which is the honest answer for a tool name that is simply wrong.
50	pub fn skill_called_as_tool_message(name: &str) -> Option<String> {
51	    let (head, tail) = name.split_once('/')?;
52	    if head.is_empty() || tail.is_empty() || tail.contains('/') {
53	        return None;
54	    }
55	    Some(format!(
56	        "'{name}' is a skill, not a tool. A skill is loaded, not called: use {LOAD_SKILL_TOOL} \
57	         with {{\"{LOAD_SKILL_ARGUMENT}\": \"{name}\"}}, then follow what it returns. \
58	         Nothing has run yet."
59	    ))
60	}
